}

use burn::tensor::{Device, Tensor};
use fabelgeist_mhr::{Mhr, MhrConfig, NUM_IDENTITY_BLEND_SHAPES};

#[test]
fn pinned_lod4_neutral_forward_is_finite() {
    let directory = std::env::var_os("FABELGEIST_MHR_PROBE_ASSETS")
        .expect("set the pinned asset directory");
    let device = Device::default();
    let model = Mhr::from_files(directory, MhrConfig::default(), &device)
        .expect("load pinned LOD4 and corrective archives");
    let identity = Tensor::zeros([1, NUM_IDENTITY_BLEND_SHAPES], &device);
    let output = model
        .forward(identity, model.zero_parameters(1), None)
        .expect("evaluate neutral model");
    assert_eq!(output.vertices.dims(), [1, 2461, 3]);
    assert_eq!(output.normals.dims(), [1, 2461, 3]);
    assert_eq!(output.skeleton_state.dims(), [1, 127, 8]);
    for (name, tensor) in [
        ("vertices", output.vertices),
        ("normals", output.normals),
        ("skeleton", output.skeleton_state),
    ] {
        let values = tensor.into_data().into_vec::<f32>().expect("read tensor");
        let nonfinite = values.iter().filter(|value| !value.is_finite()).count();
        println!("{name}: values={} nonfinite={nonfinite}", values.len());
        assert_eq!(nonfinite, 0);
    }
}

use burn::tensor::Device;
use fabelgeist_mhr::{correctives::CorrectiveImportError, CorrectiveArchiveBytes, Mhr, MhrConfig};
use std::path::PathBuf;

#[test]
fn malformed_corrective_cardinality_retains_typed_cause() {
    let assets = PathBuf::from(std::env::var_os("FABELGEIST_MHR_PROBE_ASSETS").unwrap());
    let fixture = PathBuf::from(std::env::var_os("FABELGEIST_MHR_PROBE_BAD_ACTIVATION").unwrap());
    let fbx = std::fs::read(assets.join("lod4.fbx")).unwrap();
    let definition = std::fs::read_to_string(assets.join("compact_v6_1.model")).unwrap();
    let archives = CorrectiveArchiveBytes {
        activation: std::fs::read(fixture).unwrap(),
        basis: std::fs::read(assets.join("corrective_blendshapes_lod4.npz")).unwrap(),
    };
    let error = match Mhr::from_asset_bytes(&fbx, &definition, Some(archives), MhrConfig::default(), &Device::default()) {
        Ok(_) => panic!("mismatched activation was accepted"),
        Err(error) => error,
    };
    println!("{error:#}");
    assert!(error.to_string().contains("loading the pose-corrective network"));
    assert!(matches!(error.downcast_ref::<CorrectiveImportError>(), Some(CorrectiveImportError::SparseCardinality { .. })));
}

