#[test]
fn validated_glb_accepts_different_position_and_uv_counts() {
    let mut json = br#"{"asset":{"version":"2.0"},"buffers":[{"byteLength":68}],"bufferViews":[{"buffer":0,"byteOffset":0,"byteLength":36},{"buffer":0,"byteOffset":36,"byteLength":32}],"accessors":[{"bufferView":0,"componentType":5126,"count":3,"type":"VEC3","min":[0,0,0],"max":[0,0,0]},{"bufferView":1,"componentType":5126,"count":4,"type":"VEC2"}],"meshes":[{"primitives":[{"attributes":{"POSITION":0,"TEXCOORD_0":1}}]}]}"#.to_vec();
    while json.len() % 4 != 0 { json.push(b' '); }
    let bin = [0_u8; 68];
    let length = 12 + 8 + json.len() + 8 + bin.len();
    let mut glb = b"glTF".to_vec();
    glb.extend(2_u32.to_le_bytes());
    glb.extend((length as u32).to_le_bytes());
    glb.extend((json.len() as u32).to_le_bytes());
    glb.extend(b"JSON");
    glb.extend(json);
    glb.extend((bin.len() as u32).to_le_bytes());
    glb.extend(b"BIN\0");
    glb.extend(bin);
    let doc = gltf::Gltf::from_slice(&glb).unwrap();
    let primitive = doc.meshes().next().unwrap().primitives().next().unwrap();
    let reader = primitive.reader(|_| doc.blob.as_deref());
    assert_eq!(reader.read_positions().unwrap().count(), 3);
    assert_eq!(reader.read_tex_coords(0).unwrap().into_f32().count(), 4);
}

//! Isolated investigation of compacted surface-only shell export.
#![cfg(feature = "offline-creator")]

use adventuresim_character_creator::export::{
    GlbOutput, RiggedMesh, RiggedShell, ShellTextures, export_rigged_glb,
};
use anyhow::{Context, Result};
use fabelgeist_rig::RigJointName;

#[test]
fn surface_only_compaction_exports_mismatched_attribute_counts() -> Result<()> {
    let points = [[9., 9., 9.], [0., 0., 0.], [8., 8., 8.], [1., 0., 0.], [0., 1., 0.]];
    let normals = [[0., 0., 1.]; 5];
    let uvs = [[0.1, 0.1], [0.2, 0.2], [0.3, 0.3], [0.4, 0.4], [0.5, 0.5]];
    let mut png = std::io::Cursor::new(Vec::new());
    image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(1, 1, image::Rgba([128, 128, 255, 255])))
        .write_to(&mut png, image::ImageFormat::Png)?;
    let texture = ShellTextures { normal_png: png.get_ref().clone(), metal_roughness_png: png.into_inner() };
    let names: fabelgeist_rig::RigJointTable<_> = vec![RigJointName::ROOT].into();
    let indices = fabelgeist_rig::PackedRigSkin::from_native(vec![[0; 8]; 5], names.joint_count())?;
    let weights = [[1., 0., 0., 0., 0., 0., 0., 0.]; 5];
    let shell = RiggedShell {
        textile_finish: None, plate_edges: &[], surface: Some((&uvs, &texture)),
        textures: None, texcoords: None, hinge: None, name: "surface probe",
        positions: &points, normals: &normals, faces: &[[1, 3, 4]],
        joint_indices: Some(&indices), joint_weights: Some(&weights), morph_targets: &[],
        base_color: [1.; 4], metallic: 0., roughness: 1.,
    };
    let path = std::env::temp_dir().join(format!("fabelgeist-surface-probe-{}.glb", std::process::id()));
    export_rigged_glb(GlbOutput::Standalone(&path), "probe", 1, 4, &RiggedMesh {
        joint_proportions: &Default::default(), morph_targets: &[], positions: &points,
        normals: &normals, faces: &[], export_body: false, joint_indices: &indices,
        joint_weights: &weights, joint_names: &names, joint_parents: &vec![None].into(),
        global_joint_states: &vec![[0., 0., 0., 0., 0., 0., 1., 1.]].into(),
    }, &[shell], &[])?;
    let file = gltf::Gltf::open(&path)?;
    let primitive = file.meshes().next().context("missing mesh")?.primitives().next().context("missing primitive")?;
    let counts: Vec<_> = primitive.attributes().map(|(semantic, accessor)| (semantic, accessor.count())).collect();
    assert!(counts.contains(&(gltf::Semantic::Positions, 3)));
    assert!(counts.contains(&(gltf::Semantic::TexCoords(0), 5)));
    std::fs::remove_file(path)?;
    Ok(())
}

fn main() {
    let spacing = 0.5_f32;
    let slope = 5.0e17_f32;
    let first = 0.0_f32;
    let last = 100.0_f32 * slope;
    let normal_length = (1.0_f32 + slope * slope).sqrt();
    let bottom = ((first - 6.0 - spacing * 2.0) / spacing).floor() * spacing
        - spacing * 0.5;
    let top = last + spacing * 2.0;
    let count_before_add = ((top - bottom) / spacing).ceil() as usize;
    println!("pointer_bits={} first={first:e} last={last:e} normal_length={normal_length:e} cast={count_before_add} checked_plus_one={:?}", usize::BITS, count_before_add.checked_add(1));
    assert!(last.is_finite() && normal_length.is_finite());
    assert!(count_before_add.checked_add(1).is_none());
}

