use adventuresim_tactical_core::{scene::SceneTerrain, scene_coordinates::ScenePlanPoint};
use bevy::math::Vec2;
use adventuresim_tactical_core::volumetric_terrain::{terrain_landform_patch, QuantizedLandformRecipe, TerrainGeologicStructure, TerrainLandformKind, TerrainLandformLod, TerrainLandformRecipe, TerrainSurfaceRecipe, TerrainSurfaceSource};
use adventuresim_world_schema::{SedimentaryRock, SurfaceLithology};

fn main() {
    let terrain = SceneTerrain::new(100, 100, 1.0, |point| point.x * 5.0e17)
        .expect("finite public terrain is admitted");
    for x in [-49.0_f32, 49.0] {
        let point = ScenePlanPoint::from_metres(Vec2::new(x, 0.0)).unwrap();
        println!("x={x} support={:?}", terrain.required_height_at(point));
    }
    let surface = TerrainSurfaceRecipe::from_structure(
        SurfaceLithology::Sedimentary(SedimentaryRock::Sandstone),
        TerrainSurfaceSource::AuthoredFixture,
        TerrainGeologicStructure::Massive,
    ).unwrap();
    let recipe = TerrainLandformRecipe::from_quantized(QuantizedLandformRecipe {
        kind: TerrainLandformKind::SandstoneAlcove, surface, seed: 1_u64.into(),
        origin_cm: [0, 0], tangent_permyriad: [10000, 0], relief_cm: 600,
        half_length_cm: 4500, half_width_cm: 1000, collar_cm: 250,
        lod: TerrainLandformLod::Detail,
    }).unwrap();
    println!("recipe_validate={:?}", recipe.validate(&terrain));
    let result = std::panic::catch_unwind(|| terrain_landform_patch(&terrain, recipe));
    match result {
        Ok(Ok(_)) => println!("landform=ok"),
        Ok(Err(error)) => println!("landform=error {error:?}"),
        Err(_) => println!("landform=panic"),
    }
}

